import React, { useEffect, useRef, useState } from 'react';

export default function AdBanner() {
  const [banners, setBanners] = useState([]);
  const trackRef = useRef(null);
  const animRef  = useRef(null);
  const posRef   = useRef(0);

  useEffect(() => {
    fetch('http://localhost:5000/api/banners/current')
      .then(r => r.json())
      .then(data => { if (data.banners?.length) setBanners(data.banners); })
      .catch(() => {});
  }, []);

  // Continuous smooth scroll — duplicate items for seamless loop
  useEffect(() => {
    if (!banners.length || !trackRef.current) return;
    const track = trackRef.current;
    const SPEED = 0.6; // px per frame

    const step = () => {
      posRef.current += SPEED;
      // reset when we've scrolled one full set width
      const halfWidth = track.scrollWidth / 2;
      if (posRef.current >= halfWidth) posRef.current = 0;
      track.style.transform = `translateX(-${posRef.current}px)`;
      animRef.current = requestAnimationFrame(step);
    };

    animRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(animRef.current);
  }, [banners]);

  if (!banners.length) return null;

  // Duplicate for seamless loop
  const items = [...banners, ...banners];

  return (
    <div style={wrapper}>
      <div style={track} ref={trackRef}>
        {items.map((b, i) => (
          <img
            key={i}
            src={b.url}
            alt=""
            style={img}
            draggable={false}
          />
        ))}
      </div>
    </div>
  );
}

const wrapper = {
  width: '100%',
  overflow: 'hidden',
  background: '#000',
  borderBottom: '1px solid #1a1a1a',
  height: 180,
  position: 'relative',
};

const track = {
  display: 'flex',
  alignItems: 'center',
  height: '100%',
  willChange: 'transform',
  gap: 0,
};

const img = {
  height: '100%',
  width: 'auto',
  flexShrink: 0,
  objectFit: 'cover',
  display: 'block',
  userSelect: 'none',
  pointerEvents: 'none',
};
